"use client";

import React, { useEffect, useState } from "react";
import axios from "axios";
import Image from "next/image";
import { useRouter } from "next/navigation";
import Header from "@/components/common/Header";
import Navbar from "@/components/common/Navbar";
import Footer from "@/components/common/Footer";

// Interface for cart items
interface CartItem {
  cartItemId: number;
  quantity: number;
  totalAmount: number;
  deletedAt: string | null;
  cartId: number;
  productId: number;
  productName: string;
  productImage: string;
  productPrice: number;
}

// Function to format currency manually
const formatCurrency = (value: number) => {
  return `Rp. ${value.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ".")}`;
};

const Cart = () => {
  const router = useRouter();
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const accessToken = typeof window !== "undefined" ? localStorage.getItem("token") : null;

  useEffect(() => {
    const fetchCartItems = async () => {
      if (!accessToken) {
        setError("Please log in to view your cart.");
        setLoading(false);
        return;
      }

      try {
        const response = await axios.get(
          `${process.env.NEXT_PUBLIC_API_BASE_URL}/carts/active/products`,
          {
            headers: { Authorization: `Bearer ${accessToken}` },
          }
        );

        if (response.data.success) {
          setCartItems(response.data.data);
          console.log("Fetched cart items:", response.data.data);
        } else {
          setError("Failed to fetch cart items.");
        }
      } catch (err) {
        console.error("Error fetching cart items:", err);
        setError("Error fetching cart data. Please try again.");
      } finally {
        setLoading(false);
      }
    };

    fetchCartItems();
  }, [accessToken]);

  const handleCheckout = () => {
    router.push("/checkout");
  };

  const increaseQuantity = async (productId: number) => {
    try {
      const response = await axios.put(
        `${process.env.NEXT_PUBLIC_API_BASE_URL}/carts/add`,
        {},
        {
          params: { productId },
          headers: { Authorization: `Bearer ${accessToken}` },
        }
      );
  
      if (response.status === 200) {
        setCartItems((prev: CartItem[]) =>
          prev.map((item) =>
            item.productId === productId ? { ...item, quantity: item.quantity + 1 } : item
          )
        );
        window.dispatchEvent(new Event("storage")); // Update cart icon
      }
    } catch (err) {
      console.error("Error increasing quantity:", err);
    }
  };
  
  const decreaseQuantity = async (productId: number, currentQuantity: number) => {
    if (currentQuantity === 1) return;
  
    try {
      const response = await axios.put(
        `${process.env.NEXT_PUBLIC_API_BASE_URL}/carts/subtract`,
        {},
        {
          params: { productId },
          headers: { Authorization: `Bearer ${accessToken}` },
        }
      );
  
      if (response.status === 200) {
        setCartItems((prev: CartItem[]) =>
          prev.map((item) =>
            item.productId === productId ? { ...item, quantity: item.quantity - 1 } : item
          )
        );
        window.dispatchEvent(new Event("storage")); // Update cart icon
      }
    } catch (err) {
      console.error("Error decreasing quantity:", err);
    }
  };  

  const handleRemoveItem = async (cartItemId: number) => {
    try {
      await axios.delete(`${process.env.NEXT_PUBLIC_API_BASE_URL}/carts/remove`, {
        params: { cartItemId },
        headers: { Authorization: `Bearer ${accessToken}` },
      });
  
      setCartItems((prev: CartItem[]) => prev.filter((item) => item.cartItemId !== cartItemId));
      window.dispatchEvent(new Event("storage")); // Update cart icon
    } catch (err) {
      console.error("Error removing item:", err);
    }
  };

  const totalPrice = cartItems.reduce((total, item) => total + (item.totalAmount || 0), 0);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />
      <Navbar />
      <main className="flex-grow text-black container mx-auto p-6 mt-8 mb-8 bg-white shadow-lg rounded-lg">
        <h2 className="text-2xl font-bold mb-6">Shopping Cart</h2>

        {loading && <p>Loading cart items...</p>}
        {error && <p className="text-red-500">{error}</p>}
        {!loading && !error && cartItems.length === 0 && <p>Your cart is empty.</p>}

        <div className="space-y-6">
          {cartItems.map((item) => (
            <div key={item.cartItemId} className="flex items-center border-b border-gray-300 pb-4">
              <Image
                src={item.productImage || "/images/default-product.jpg"}
                alt={item.productName}
                width={80}
                height={80}
                className="rounded-lg"
              />
              <div className="ml-4 flex-1">
                <h3 className="text-lg font-semibold">{item.productName}</h3>
                <p className="text-gray-600">{formatCurrency(item.productPrice)}</p>
                <div className="mt-2 flex items-center space-x-2">
                  <button
                    onClick={() => decreaseQuantity(item.productId, item.quantity)}
                    disabled={item.quantity <= 1}
                    className="px-3 py-1 bg-gray-200 text-black rounded-lg"
                  >
                    -
                  </button>
                  <span className="px-4 py-1 bg-gray-100 rounded-lg">{item.quantity}</span>
                  <button
                    onClick={() => increaseQuantity(item.productId)}
                    className="px-3 py-1 bg-gray-200 text-black rounded-lg"
                  >
                    +
                  </button>
                </div>
              </div>
              <button
                onClick={() => handleRemoveItem(item.cartItemId)}
                className="ml-4 text-red-500 hover:text-red-700"
              >
                Remove
              </button>
            </div>
          ))}
        </div>

        <div className="mt-8 flex justify-between items-center">
          <p className="text-xl font-semibold">Total: {formatCurrency(totalPrice)}</p>
          <button
            onClick={handleCheckout}
            className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-500"
          >
            Checkout
          </button>
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Cart;
